def comps(g):
    m,n=len(g),len(g[0]); seen=[[False]*n for _ in range(m)]; cl=[]
    for i in range(m):
        for j in range(n):
            if g[i][j] and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True;s=[]
                while st:
                    a,b=st.pop()
                    s.append((a,b))
                    for d in(-1,0,1):
                        for e in(-1,0,1):
                            x,y=a+d,b+e
                            if 0<=x<m and 0<=y<n and g[x][y]==g[a][b] and not seen[x][y]:
                                seen[x][y]=True; st.append((x,y))
                cl.append(s)
    return cl
