def f(g):
    h=len(g); w=len(g[0])
    s=None
    for i in range(h):
        r=g[i]
        if len(set(r))==1 and r[0]!=0: s=i; break
    res=[[0]*w for _ in range(s)]
    low=g[s+1:]
    for i in range(len(res)):
        for j in range(w):
            if g[i][j]!=0 and low[i][j]!=0: res[i][j]=2
    return res
